# Bám sách: trang 48–49 + đáp án + Mini dictionary unit 22. Không chép nguyên văn.
theory = (
 H("A", "Supporting and opposing people or views", "Ủng hộ và phản đối người hoặc quan điểm")
 + P("In television interviews, Members of Parliament (MPs) defend the positions they have taken.",
     "Trong các cuộc phỏng vấn truyền hình, các nghị sĩ (MP) bảo vệ lập trường của mình.")
 + T([
    ("<b>come out against</b> (opposite: <b>come out in favour of</b>)", "The MP has said publicly that she opposes colleagues who want stronger anti-terrorist laws.", "Nghị sĩ đã công khai phản đối những đồng nghiệp muốn luật chống khủng bố cứng rắn hơn."),
    ("<b>stick by</b> / <b>side with</b>", "She keeps supporting what she has always said; people who support terrorists in an argument must be opposed.", "Bà vẫn giữ quan điểm từ trước tới nay; ai đứng về phía khủng bố thì phải bị phản đối."),
    ("<b>lean towards</b> / <b>cross over</b>", "The interviewer suggests he is starting to support more conservative policies and may move to the Conservative Party.", "Người phỏng vấn cho rằng ông đang ngả về chính sách bảo thủ và có thể chuyển sang đảng Bảo thủ."),
    ("<b>stand for</b> / <b>side against</b>", "He says he supports liberal values, but sees no reason to oppose the Conservatives when he agrees with them.", "Ông nói mình theo giá trị tự do, nhưng không thấy lý do chống đảng Bảo thủ ở những vấn đề ông đồng ý với họ."),
    ("<b>cave in</b>", "After opposition from trucking companies, the minister seems to have agreed to drop higher fuel charges.", "Sau phản đối của các công ty vận tải, bộ trưởng dường như đã nhượng bộ, bỏ việc tăng phí nhiên liệu."),
    ("<b>defer to</b> / <b>go with</b>", "(formal) The party accepts expert opinion because experts know more, and has decided to accept that advice.", "(trang trọng) Đảng nghe theo ý kiến chuyên gia vì họ hiểu biết hơn, và đã quyết định theo lời khuyên đó."),
 ])
 + H("B", "Supporting and opposing in newspaper extracts", "Ủng hộ và phản đối trong các trích đoạn báo")
 + T([
    ("<b>egg on</b>", "A 17-year-old says his friends encouraged him to steal cars.", "Một thiếu niên 17 tuổi nói bạn bè đã xúi cậu trộm xe."),
    ("<b>cheer on</b>", "An athlete broke the world record while her supporters shouted encouragement.", "Một vận động viên phá kỷ lục thế giới trong tiếng cổ vũ của người hâm mộ."),
    ("<b>swear by</b>", "A 104-year-old woman believes a glass of hot milk at bedtime really works.", "Một cụ bà 104 tuổi tin chắc cốc sữa nóng trước khi ngủ rất hiệu nghiệm."),
    ("<b>not hear of</b>", "A club will not allow children to attend an event (always negative).", "Một câu lạc bộ không cho phép trẻ em tham dự sự kiện (luôn ở dạng phủ định)."),
    ("<b>buoy up</b>", "A large donation supported a peace campaign and made it more successful.", "Một khoản quyên góp lớn tiếp sức cho chiến dịch hòa bình."),
    ("<b>stick up for</b>", "(informal) A man who always defended the rights of poor and homeless people.", "(thân mật) Một người luôn đấu tranh cho quyền của người nghèo và vô gia cư."),
 ])
 + NOTE("<b>Exercise 22.3 – other meanings of the same word</b>: <b>stick</b> a stamp on a card; the left-hand <b>side</b> of a page; <b>cheer</b> someone up / a <b>cheer</b> went up; sail round a red <b>buoy</b>. <b>22.4 – particle errors</b>: go <b>with</b> (not get with), cross <b>over</b> (not across), defer <b>to</b> (not on), <b>swear by</b> (not promise by), egg <b>on</b> (not off).",
        "<b>Bài 22.3 – nghĩa khác của cùng một từ</b>: <b>stick</b> dán tem lên bưu thiếp; <b>side</b> = bên trái của trang; <b>cheer</b> ai đó lên / một tràng <b>cheer</b> vang lên; lái thuyền vòng qua chiếc <b>buoy</b> (phao) đỏ. <b>22.4 – lỗi tiểu từ</b>: go <b>with</b> (không phải get with), cross <b>over</b> (không phải across), defer <b>to</b> (không phải on), <b>swear by</b> (không phải promise by), egg <b>on</b> (không phải off).")
)
